/// Legacy root matrix fingerprint; its tag is retained for existing receipts.
/// Undefined raw ratios are opaque stored pairs, never admitted rational values.
pub fn hash_exact_matrix(m: &ExactMatrix<Q>) -> Hash256 {
    hash_legacy_matrix(&m.0)
}

fn hash_legacy_matrix(m: &crate::linear_algebra::BasicMatrix<Q>) -> Hash256 {
    let mut hasher = blake3::Hasher::new();
    hasher.update(b"TheoryOfFiniteQM.ExactMatrix<Q>.v1");
    hasher.update(&(m.rows() as u64).to_le_bytes());
    hasher.update(&(m.cols() as u64).to_le_bytes());
    for val in m.as_slice() {
        hashing::hash_stored_rational(&mut hasher, val);
    }
    Hash256(*hasher.finalize().as_bytes())
}

/// Compatibility facade over the single admitted carrier. Serialization is data;
/// deserialization recomputes the law, ranks and hashes instead of trusting bytes.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(try_from = "CarrierWire")]
pub struct Carrier {
    inner: carrier::Carrier,
}

#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct CarrierWire {
    c0_dim: usize,
    c1_dim: usize,
    c2_dim: usize,
    d0: ExactMatrix<Q>,
    d1: ExactMatrix<Q>,
    weights: Vec<Q>,
    d0_hash: Hash256,
    d1_hash: Hash256,
}

/// Borrow the existing wire fields without cloning the carrier's certificates
/// or coefficient buffers. Preserve both Serde struct and newtype identities.
#[derive(Serialize)]
#[serde(rename = "CarrierWire")]
struct CarrierWireRef<'a> {
    c0_dim: usize,
    c1_dim: usize,
    c2_dim: usize,
    #[serde(serialize_with = "serialize_matrix_ref")]
    d0: &'a crate::linear_algebra::BasicMatrix<Q>,
    #[serde(serialize_with = "serialize_matrix_ref")]
    d1: &'a crate::linear_algebra::BasicMatrix<Q>,
    weights: &'a [Q],
    d0_hash: Hash256,
    d1_hash: Hash256,
}

fn serialize_matrix_ref<S: serde::Serializer>(
    matrix: &&crate::linear_algebra::BasicMatrix<Q>,
    serializer: S,
) -> Result<S::Ok, S::Error> {
    serializer.serialize_newtype_struct("ExactMatrix", *matrix)
}

impl Serialize for Carrier {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        CarrierWireRef {
            c0_dim: self.c0_dim(),
            c1_dim: self.c1_dim(),
            c2_dim: self.c2_dim(),
            d0: self.d0(),
            d1: self.d1(),
            weights: self.weights(),
            d0_hash: hash_legacy_matrix(self.d0()),
            d1_hash: hash_legacy_matrix(self.d1()),
        }
        .serialize(serializer)
    }
}

impl Carrier {
    pub fn new(
        c0_dim: usize,
        c1_dim: usize,
        c2_dim: usize,
        d0: ExactMatrix<Q>,
        d1: ExactMatrix<Q>,
        weights: Vec<Q>,
    ) -> Result<Self, HomologicalError> {
        let provenance =
            cochain_complex::TheoremProvenance::new("runtime exact d1*d0 verification".into())?;
        Ok(Self {
            inner: carrier::Carrier::new(c0_dim, c1_dim, c2_dim, d0.0, d1.0, weights, provenance)?,
        })
    }
    pub fn c0_dim(&self) -> usize {
        self.inner.c0_dim()
    }
    pub fn c1_dim(&self) -> usize {
        self.inner.c1_dim()
    }
    pub fn c2_dim(&self) -> usize {
        self.inner.c2_dim()
    }
    pub fn d0(&self) -> &crate::linear_algebra::BasicMatrix<Q> {
        self.inner.d0()
    }
    pub fn d1(&self) -> &crate::linear_algebra::BasicMatrix<Q> {
        self.inner.d1()
    }
    pub fn weights(&self) -> &[Q] {
        self.inner.weights()
    }
    pub fn rank_d0(&self) -> usize {
        self.inner.rank_d0()
    }
    pub fn rank_d1(&self) -> usize {
        self.inner.rank_d1()
    }
    pub fn dim_q1(&self) -> usize {
        self.c1_dim() - self.rank_d0()
    }
    pub fn dim_h1(&self) -> Result<usize, HomologicalError> {
        self.inner.dim_h1()
    }
}

impl AsRef<carrier::Carrier> for Carrier {
    fn as_ref(&self) -> &carrier::Carrier {
        &self.inner
    }
}

impl TryFrom<CarrierWire> for Carrier {
    type Error = HomologicalError;
    fn try_from(value: CarrierWire) -> Result<Self, Self::Error> {
        verify_hash(&value.d0_hash, &hash_exact_matrix(&value.d0))?;
        verify_hash(&value.d1_hash, &hash_exact_matrix(&value.d1))?;
        Self::new(
            value.c0_dim,
            value.c1_dim,
            value.c2_dim,
            value.d0,
            value.d1,
            value.weights,
        )
    }
}

fn verify_hash(expected: &Hash256, got: &Hash256) -> Result<(), HomologicalError> {
    if expected != got {
        return Err(HomologicalError::HashMismatch {
            expected: expected.to_hex(),
            got: got.to_hex(),
        });
    }
    Ok(())
}

//! Compatibility facade for the admitted rational carrier. AuthorityEffect: None.
//!
//! All three carrier entry points share the same immutable law-checked core.

use super::cochain_complex::TheoremProvenance;
use crate::linear_algebra::basic_matrix::BasicMatrix;
use crate::linear_algebra::scalars::{q, Q};
use std::collections::BTreeMap;

pub use super::carrier_manifest::CarrierManifest;
pub use super::errors::HomologicalError as CarrierError;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Carrier {
    inner: super::carrier::Carrier,
}

impl AsRef<super::carrier::Carrier> for Carrier {
    fn as_ref(&self) -> &super::carrier::Carrier {
        &self.inner
    }
}

impl Carrier {
    pub fn new(
        c0_dim: usize,
        c1_dim: usize,
        c2_dim: usize,
        d0: BasicMatrix<Q>,
        d1: BasicMatrix<Q>,
        weights: Vec<Q>,
    ) -> Result<Self, CarrierError> {
        let provenance = TheoremProvenance::new("runtime exact d1*d0 verification".into())?;
        Ok(Self {
            inner: super::carrier::Carrier::new(
                c0_dim, c1_dim, c2_dim, d0, d1, weights, provenance,
            )?,
        })
    }
    pub fn c0_dim(&self) -> usize {
        self.inner.c0_dim()
    }
    pub fn c1_dim(&self) -> usize {
        self.inner.c1_dim()
    }
    pub fn c2_dim(&self) -> usize {
        self.inner.c2_dim()
    }
    pub fn d0(&self) -> &BasicMatrix<Q> {
        self.inner.d0()
    }
    pub fn d1(&self) -> &BasicMatrix<Q> {
        self.inner.d1()
    }
    pub fn weights(&self) -> &[Q] {
        self.inner.weights()
    }
    pub fn rank_d0(&self) -> usize {
        self.inner.rank_d0()
    }
    pub fn rank_d1(&self) -> usize {
        self.inner.rank_d1()
    }
    pub fn dim_q1(&self) -> usize {
        self.c1_dim() - self.rank_d0()
    }
    /// Rank inclusion was checked during construction; subtraction cannot underflow.
    pub fn dim_h1(&self) -> usize {
        self.c1_dim() - self.rank_d1() - self.rank_d0()
    }
}

/// Signed incidence carrier for a finite simple directed presentation.
/// Triangles (a,b,c) require edges a->b, b->c and a->c. Missing edges,
/// repeated vertices, parallel edges and self loops are rejected explicitly.
/// Construction costs O(E log E + T log E) table work, plus exact law/rank checks.
/// Opposite directed edges are distinct; duplicate directed edges are refused.
/// Triangle rows may repeat. Only repeated vertices within one triangle are
/// refused; each supplied triangle contributes its own signed row.
pub fn graph_carrier(
    num_nodes: usize,
    edges: &[(usize, usize)],
    triangles: &[(usize, usize, usize)],
    weights: Vec<Q>,
) -> Result<Carrier, CarrierError> {
    let indices = edge_indices(num_nodes, edges)?;
    let mut d0 = BasicMatrix::<Q>::zero(edges.len(), num_nodes)?;
    for (i, &(src, tgt)) in edges.iter().enumerate() {
        d0.set(i, src, q(-1))?;
        d0.set(i, tgt, q(1))?;
    }
    let d1 = triangle_boundary(num_nodes, edges.len(), triangles, &indices)?;
    Carrier::new(num_nodes, edges.len(), triangles.len(), d0, d1, weights)
}

fn triangle_boundary(
    num_nodes: usize,
    num_edges: usize,
    triangles: &[(usize, usize, usize)],
    indices: &BTreeMap<(usize, usize), usize>,
) -> Result<BasicMatrix<Q>, CarrierError> {
    let mut d1 = BasicMatrix::<Q>::zero(triangles.len(), num_edges)?;
    for (i, &(a, b, c)) in triangles.iter().enumerate() {
        admit_triangle(num_nodes, i, (a, b, c))?;
        for (src, tgt, sign) in [(a, b, 1), (b, c, 1), (a, c, -1)] {
            let col = indices
                .get(&(src, tgt))
                .ok_or(CarrierError::TriangleMissingEdge {
                    triangle: i,
                    src,
                    tgt,
                })?;
            d1.set(i, *col, q(sign))?;
        }
    }
    Ok(d1)
}

fn edge_indices(
    num_nodes: usize,
    edges: &[(usize, usize)],
) -> Result<BTreeMap<(usize, usize), usize>, CarrierError> {
    let mut indices = BTreeMap::new();
    for (i, &(src, tgt)) in edges.iter().enumerate() {
        admit_edge(num_nodes, i, src, tgt)?;
        if indices.insert((src, tgt), i).is_some() {
            return Err(CarrierError::BasisMismatch {
                description: "parallel directed edges".into(),
            });
        }
    }
    Ok(indices)
}

fn admit_edge(n: usize, edge: usize, src: usize, tgt: usize) -> Result<(), CarrierError> {
    if src >= n {
        return Err(CarrierError::EdgeSourceOutOfRange { edge, src });
    }
    if tgt >= n {
        return Err(CarrierError::EdgeTargetOutOfRange { edge, tgt });
    }
    if src == tgt {
        return Err(CarrierError::SelfLoopNotAllowed { node: src });
    }
    Ok(())
}

fn admit_triangle(
    n: usize,
    triangle: usize,
    (a, b, c): (usize, usize, usize),
) -> Result<(), CarrierError> {
    for vertex in [a, b, c] {
        if vertex >= n {
            return Err(CarrierError::TriangleVertexOutOfRange { triangle, vertex });
        }
    }
    if a == b || b == c || a == c {
        return Err(CarrierError::BasisMismatch {
            description: "triangle vertices must be distinct".into(),
        });
    }
    Ok(())
}
